(()=>{
'use strict';
const p=location.pathname;
const page=p.includes('trail-camera-photo-sorting-software')?'sorting':p.includes('offline-trail-camera-software')?'offline':p.includes('camera-trap-software-for-researchers')?'research':p.includes('trail-camera-software-for-hunters')?'hunters':p.includes('best-ai-trail-camera-software')?'best':null;
const lang=new URLSearchParams(location.search).get('lang')||localStorage.getItem('traileye-lang')||'en';
if(!page||lang==='en')return;
const D={
sorting:{
 de:{hero:'TrailEye AI prüft einen Kameraordner lokal, findet Ereignisse mit Tieren, Menschen und Fahrzeugen, verfeinert unterstützte Wildtierarten und erstellt ein durchsuchbares Archiv. Du behältst die Kontrolle über jedes Ergebnis.',proof:'Echte TrailEye-AI-Oberfläche: Originalbild, Erkennungsdetails, Timeline und Prüfwerkzeuge in einer Ansicht.',intro:['TrailEye ist für gewöhnliche Wildkamera-Ordner konzipiert. Es erfordert weder eine bestimmte Kameramarke noch ein Cloud-Kamera-Abo.'],cards:['Wähle einen Ordner mit unterstützten Fotos, Videos oder beidem. Die Quelldateien bleiben an ihrem Ort.','Die lokale Pipeline erkennt Tiere, Menschen und Fahrzeuge und verfeinert unterstützte Wildtierarten.','Prüfe Erkennungen, lehne Fehlalarme ab, korrigiere unsichere Ergebnisse und wechsle per Tastatur zwischen Ereignissen.','TrailEye liest eingeblendete Zeitstempel per OCR und nutzt bei Bedarf EXIF- oder Dateizeit.','Filtere nach Art und untersuche Aktivität nach Stunde, Tag, Sonnenphase, Kamerastandort und weiterem Kontext.','Exportiere ausgewählte Daten, Bilder und Berichte, statt Erkenntnisse im Kameraordner zu belassen.'],prose:['Eine gute Sortiersoftware sollte wiederholte Sichtung reduzieren, ohne das Originalmaterial zu verbergen. TrailEye verknüpft jedes Ergebnis mit der Quelldatei und erlaubt Korrekturen der KI. Nachtbilder, teilweise sichtbare Tiere, Vegetation, Wetter und geringe Auflösung können jedes Modell herausfordern.','Ziel ist nicht, jede Vorhersage als perfekt darzustellen. Wahrscheinliche Ereignisse sollen hervorgehoben, Kontext bewahrt und die menschliche Prüfung schneller und konsistenter gemacht werden.','Viele Wildkamera-Archive enthalten Fotos und kurze Videos. TrailEye verarbeitet beides im selben ordnerbasierten Workflow, sodass kein separater manueller Prozess nötig ist.','Die erste Erkennungsstufe unterscheidet Tiere, Menschen und Fahrzeuge. So können Jäger und Naturbeobachter Tierereignisse fokussieren, während Landverwalter relevante Personen- oder Fahrzeugaktivität finden können. TrailEye identifiziert keine einzelnen Personen und muss gemäß lokalem Recht verwendet werden.','Free bleibt dauerhaft kostenlos und erfordert keine Zahlungsdaten. Explorer und Professional sind Einmalkäufe statt Abonnements.','Die Verarbeitungsgeschwindigkeit hängt von Dateigröße, Medientyp und Windows-Hardware ab. Kompatible Grafikhardware kann DirectML nutzen. Die KI-Sicherheit variiert mit Entfernung, Licht, Bewegungsunschärfe, Kameraposition und Sichtbarkeit des Tieres. Wichtige Klassifikationen sollten von einem Menschen geprüft werden.'],lis:['Free: bis zu 20 Fotos oder Videos pro Analyse mit vollständiger KI-Erkennung.','Explorer: bis zu 1.000 Dateien aus einem Ordner pro Analyse auf einem Computer.','Professional: unbegrenzte Dateien, Unterordner und Aktivierung auf bis zu drei Computern.'],related:['Erfahre, was lokal läuft und wann eine Netzwerkverbindung genutzt werden kann.','KI-gestützte Vorauswahl, Korrekturen, Zeitstempel, Karten und Exporte für Feldprojekte.','Saisonale Kameraordner prüfen und Wildtieraktivität nach Zeit und Ort finden.'],cta:'Dauerhaft kostenlose Version · Vollständige KI-Erkennung · Keine Kreditkarte'},
 sl:{hero:'TrailEye AI lokalno pregleda mapo kamere, izloči dogodke z živalmi, ljudmi in vozili, prepozna podprte vrste ter zgradi iskalni arhiv. Nad vsakim rezultatom ohranite nadzor.',proof:'Pravi vmesnik TrailEye AI: izvirna slika, podrobnosti zaznave, časovnica in orodja za pregled na enem mestu.',intro:['TrailEye je narejen za običajne mape lovskih kamer. Ne zahteva določene znamke kamere ali naročnine na storitev v oblaku.'],cards:['Izberite mapo s podprtimi fotografijami, videi ali obojim. Izvorne datoteke ostanejo na svojem mestu.','Lokalni sistem zazna živali, ljudi in vozila ter pri podprtih živalih poskuša določiti vrsto.','Preglejte zaznave, zavrnite napačne, popravite negotove rezultate in se med dogodki premikajte z bližnjicami.','TrailEye z OCR prebere časovne oznake na sliki ter po potrebi uporabi EXIF ali čas datoteke.','Filtrirajte po vrsti ter preverite aktivnost po urah, dnevih, delu dneva, lokaciji kamere in drugem kontekstu.','Izvozite izbrane podatke, slike in poročila, namesto da ugotovitve ostanejo ujete v mapi kamere.'],prose:['Dober program mora zmanjšati ponavljajoče pregledovanje, ne da bi skril izvirni posnetek. TrailEye ohrani povezavo z izvorno datoteko in omogoča popravljanje odločitev AI. Nočni posnetki, delno vidne živali, vegetacija, vreme in nizka ločljivost lahko zmedejo vsak model.','Cilj ni trditi, da je vsaka napoved popolna. Cilj je izpostaviti verjetne dogodke, ohraniti kontekst ter pohitriti in poenotiti človeški pregled.','Veliko arhivov vsebuje fotografije in kratke videe. TrailEye oboje obdeluje v istem poteku dela po mapah, zato za vsak tip medija ne potrebujete ločenega postopka.','Prva stopnja zaznavanja loči živali, ljudi in vozila. Tako se lahko lovci in opazovalci osredotočijo na živalske dogodke, upravljavci pa najdejo tudi pomembno človeško ali prometno aktivnost. TrailEye ne prepoznava posameznih oseb in ga je treba uporabljati skladno z zakonodajo.','Free je trajno brezplačen in ne zahteva plačilnih podatkov. Explorer in Professional sta enkratna nakupa brez naročnine.','Hitrost je odvisna od velikosti datotek, vrste medija in strojne opreme Windows. Združljiva grafična kartica lahko pospeši lokalni AI prek DirectML. Zanesljivost AI je odvisna tudi od razdalje, svetlobe, zameglitve, postavitve kamere in vidnosti živali. Pomembne razvrstitve naj preveri človek.'],lis:['Free: do 20 fotografij ali videov na analizo s celotnim AI prepoznavanjem.','Explorer: do 1.000 datotek iz ene mape na analizo na enem računalniku.','Professional: neomejeno datotek, podmape in aktivacija na do treh računalnikih.'],related:['Preverite, kaj deluje lokalno in kdaj je lahko uporabljena internetna povezava.','AI predizbor, popravki, časovne oznake, zemljevidi in izvozi za terenske projekte.','Preglejte sezonske mape in poiščite aktivnost živali po času in lokaciji.'],cta:'Trajno brezplačna različica · Celotno AI prepoznavanje · Brez kreditne kartice'},
 es:{hero:'TrailEye AI revisa una carpeta localmente, detecta eventos con animales, personas y vehículos, refina especies compatibles y crea un archivo buscable. Tú mantienes el control de cada resultado.',proof:'Interfaz real de TrailEye AI: imagen original, detalles de detección, línea temporal y controles de revisión en una vista.',intro:['TrailEye está diseñado para carpetas normales de cámaras trampa. No requiere una marca concreta ni una suscripción a una cámara en la nube.'],cards:['Selecciona una carpeta con fotos, vídeos o ambos. Los archivos originales permanecen donde están.','La canalización local detecta animales, personas y vehículos e intenta refinar especies compatibles.','Revisa detecciones, rechaza falsos positivos, cambia etiquetas dudosas y recorre eventos con atajos de teclado.','TrailEye lee marcas de tiempo incrustadas con OCR y usa EXIF o la hora del archivo como respaldo.','Filtra por especie y revisa actividad por hora, día, periodo solar, ubicación de cámara y otro contexto disponible.','Exporta datos, imágenes e informes seleccionados en lugar de dejar los hallazgos dentro de una carpeta.'],prose:['Un buen clasificador debe reducir la revisión repetitiva sin ocultar la evidencia original. TrailEye mantiene cada resultado unido al archivo fuente y permite corregir decisiones de IA. Las imágenes nocturnas, animales parciales, vegetación, clima y baja resolución pueden desafiar cualquier modelo.','El objetivo no es fingir que cada predicción es perfecta, sino destacar eventos probables, conservar el contexto y acelerar la revisión humana.','Muchos archivos contienen fotos y clips cortos. TrailEye procesa ambos en el mismo flujo basado en carpetas, sin procesos manuales separados.','La primera etapa distingue animales, personas y vehículos. Esto ayuda a centrarse en fauna y también a localizar actividad humana o de vehículos relevante. TrailEye no identifica personas concretas y debe usarse conforme a la legislación local.','Free es permanente y no requiere datos de pago. Explorer y Professional son compras únicas, no suscripciones.','La velocidad depende del tamaño de archivo, tipo de medio y hardware Windows. DirectML puede acelerar la inferencia. La confianza de IA varía con distancia, iluminación, desenfoque, colocación de cámara y visibilidad del animal. Las clasificaciones importantes deben revisarse.'],lis:['Free: hasta 20 fotos o vídeos por análisis con reconocimiento IA completo.','Explorer: hasta 1.000 archivos de una carpeta por análisis en un ordenador.','Professional: archivos ilimitados, subcarpetas y hasta tres ordenadores.'],related:['Consulta qué funciona localmente y cuándo puede utilizarse una conexión de red.','Cribado asistido por IA, correcciones, tiempos, mapas y exportaciones para proyectos de campo.','Revisa carpetas de temporada y encuentra actividad por tiempo y lugar.'],cta:'Edición gratuita permanente · Reconocimiento IA completo · Sin tarjeta'},
 ru:{hero:'TrailEye AI локально анализирует папку камеры, находит события с животными, людьми и транспортом, уточняет поддерживаемые виды и создаёт доступный для поиска архив. Вы контролируете каждый результат.',proof:'Реальный интерфейс TrailEye AI: исходное изображение, детали обнаружения, временная шкала и инструменты проверки в одном окне.',intro:['TrailEye рассчитан на обычные папки фотоловушек. Он не требует конкретной марки камеры или облачной подписки.'],cards:['Выберите папку с поддерживаемыми фото, видео или обоими типами. Исходные файлы остаются на месте.','Локальный конвейер обнаруживает животных, людей и транспорт и уточняет поддерживаемые виды.','Проверяйте обнаружения, отклоняйте ложные срабатывания, меняйте сомнительные метки и переходите между событиями горячими клавишами.','TrailEye читает встроенные метки времени через OCR и при необходимости использует EXIF или время файла.','Фильтруйте по виду и изучайте активность по часу, дню, солнечному периоду, месту камеры и другому контексту.','Экспортируйте выбранные данные, изображения и отчёты вместо того, чтобы оставлять результаты в папке камеры.'],prose:['Полезный сортировщик должен сокращать повторную проверку, не скрывая исходные доказательства. TrailEye сохраняет связь результата с исходным файлом и позволяет исправлять решения ИИ. Ночные кадры, частично видимые животные, растительность, погода и низкое разрешение могут затруднить работу любой модели.','Цель не в том, чтобы считать каждое предсказание идеальным, а в том, чтобы вывести вероятные события вперёд, сохранить контекст и ускорить человеческую проверку.','Многие архивы содержат и фотографии, и короткие видео. TrailEye обрабатывает их в одном папочном процессе.','Первый этап различает животных, людей и транспорт. Это помогает сосредоточиться на животных и при необходимости найти человеческую или транспортную активность. TrailEye не идентифицирует отдельных людей и должен использоваться в соответствии с законом.','Free остаётся бесплатной и не требует платёжных данных. Explorer и Professional приобретаются один раз.','Скорость зависит от размера файлов, типа медиа и оборудования Windows. Совместимая графика может ускорить ИИ через DirectML. Уверенность зависит от расстояния, света, смаза, положения камеры и видимости животного. Важные классификации следует проверять вручную.'],lis:['Free: до 20 фото или видео за анализ с полным ИИ-распознаванием.','Explorer: до 1 000 файлов из одной папки за анализ на одном компьютере.','Professional: без ограничения файлов, с подпапками и активацией на трёх компьютерах.'],related:['Узнайте, что работает локально и когда может использоваться сеть.','ИИ-предварительный отбор, исправления, время, карты и экспорт для полевых проектов.','Проверяйте сезонные папки и находите активность по времени и месту.'],cta:'Постоянная бесплатная версия · Полное ИИ-распознавание · Без банковской карты'},
 zh:{hero:'TrailEye AI 在本地审核相机文件夹，找出动物、人员和车辆事件，细化支持的野生动物物种，并建立可搜索档案。每个结果都由你掌控。',proof:'真实的 TrailEye AI 界面：原始图像、检测详情、时间轴和审核控件集中在一个视图中。',intro:['TrailEye 面向普通野外相机文件夹设计，不要求特定相机品牌或云相机订阅。'],cards:['选择包含支持的照片、视频或两者的文件夹。源文件保持原位。','本地流程检测动物、人员和车辆，并尝试细化支持的野生动物物种。','审核检测结果、拒绝误报、重新标记不确定结果，并使用快捷键浏览事件。','TrailEye 使用 OCR 读取画面中的时间戳，并在需要时使用 EXIF 或文件时间。','按物种筛选，并按小时、日期、太阳时段、相机位置及其他上下文查看活动。','导出选定的数据、图像和报告，而不是让有用发现留在相机文件夹中。'],prose:['好的分类器应减少重复审核，同时保留原始证据。TrailEye 将每个结果与源文件关联，并允许修正 AI 决策。夜间图像、局部动物、植被、天气和低分辨率都可能挑战任何识别模型。','目标不是假装每个预测都完美，而是优先呈现可能事件、保留上下文并让人工审核更快、更一致。','很多野外相机档案同时包含照片和短视频。TrailEye 通过同一文件夹工作流程处理二者，无需为不同媒体单独操作。','第一阶段区分动物、人员和车辆，既方便关注动物事件，也能查找相关人员或车辆活动。TrailEye 不识别具体个人，使用时应遵守当地法律。','Free 永久免费且无需支付信息。Explorer 和 Professional 为一次性购买，不是订阅。','处理速度取决于文件大小、媒体类型和 Windows 硬件。兼容显卡可通过 DirectML 加速本地推理。AI 置信度也受距离、光照、运动模糊、相机位置和动物可见程度影响。重要分类应由人工确认。'],lis:['Free：每次分析最多 20 张照片或视频，提供完整 AI 识别。','Explorer：每次从一个文件夹处理最多 1,000 个文件，可在一台电脑上使用。','Professional：文件不限量、支持子文件夹并可激活三台电脑。'],related:['了解哪些功能在本地运行，以及何时可能使用网络连接。','用于现场项目的 AI 初筛、修正、时间戳、地图和导出。','审核季节相机文件夹，并按时间和地点查找野生动物活动。'],cta:'永久免费版 · 完整 AI 识别 · 无需信用卡'}
},
offline:{
 de:{hero:'TrailEye AI analysiert Wildkamera-Fotos und -Videos auf deinem Windows-PC. Der Standard-Workflow für Erkennung und Archivierung erfordert keinen Upload in eine Cloud-Galerie.',proof:'Private Standorte, Zeitstempel und Kameraordner können unter deiner Kontrolle auf dem Windows-PC bleiben.',intro:['Ein Wildkamera-Archiv kann Menschen, Fahrzeuge, Privatgrundstücke, genaue Kamerapositionen und Beobachtungen sensibler Arten enthalten. Lokale Verarbeitung reduziert die Notwendigkeit, dieses Archiv an andere Dienste zu übertragen.'],cards:['TrailEye liest Dateien aus den ausgewählten Ordnern und erstellt sein Arbeitsarchiv lokal.','Kernfunktionen für Erkennung und Prüfung können ohne Upload großer Kameraordner genutzt werden.','Kamerapositionen und Wildtierbeobachtungen müssen nicht Teil einer verpflichtenden Anbieter-Cloud werden.','Free bleibt dauerhaft kostenlos. Explorer und Professional sind als Einmallizenzen verfügbar.','Vorhersagen können bestätigt, abgelehnt oder neu beschriftet werden, statt KI als endgültige Autorität zu behandeln.','Der Workflow ist nicht auf eine einzige verbundene Kameramarke oder ein Abo-Ökosystem beschränkt.'],prose:['Die Standard-Pipeline von TrailEye analysiert Bilder und Videos auf dem Windows-PC auf Tiere, Menschen und Fahrzeuge. Unterstützte Tiere können in eine Bibliothek unterstützter Arten verfeinert werden. OCR, Prüfung, Filter, Aktivitätsansichten, Karten und Exporte gehören zum Desktop-Workflow.','Kompatible Windows-Grafikhardware kann die KI mit DirectML beschleunigen. Eine Netzwerkverbindung ist nicht nötig, nur um jede Quelldatei in eine gehostete Galerie zu schicken.','„Local-first“ bedeutet nicht, dass die Anwendung niemals mit einem Netzwerkdienst kommuniziert. Je nach Funktion können Kartenkacheln, Software- oder Lizenzprüfung und eine optionale Cloud-Suche genutzt werden.','Die optionale Cloud-Suche ist vom lokalen Detektor getrennt, benötigt den eigenen API-Schlüssel des Nutzers und sendet ausgewählte Bilddaten an den gewählten Anbieter. Bei strikt offline geführten Projekten sollte sie deaktiviert bleiben.','Lokale Datenhaltung hilft bei der Kontrolle, aber der Kamerabetreiber bleibt für rechtmäßige Platzierung, Zugriff, Aufbewahrung und Weitergabe verantwortlich. Bilder von Personen, Fahrzeugen oder Nachbargrundstücken können sensible Daten sein.','Cloud-Plattformen sind sinnvoll, wenn sofortige Fernübertragung, Zusammenarbeit oder Mobilfunkkameras im Mittelpunkt stehen. Lokale Desktop-Software passt besser zu SD-Karten oder Festplatten, begrenzter Bandbreite, sensiblen Standorten oder einem unabhängigen Archiv.','TrailEye soll nicht jede Cloud-Funktion ersetzen. Es bietet einen zugänglichen Windows-Workflow von normalen Kameraordnern zu geprüften, durchsuchbaren Ergebnissen.'],lis:['Kameras nur dort aufstellen, wo eine rechtmäßige Grundlage und Befugnis besteht.','Zugriff auf Ordner, Berichte und exportierte Bilder begrenzen.','Genaue Standorte aus öffentlich geteiltem Material entfernen.','Gesichter und Kennzeichen in öffentlichen oder werblichen Beispielen bei Bedarf unkenntlich machen.','Wichtige KI-Klassifikationen vor Entscheidungen menschlich prüfen.'],related:['Von Rohordnern zu geprüften Tier-, Personen- und Fahrzeugereignissen.','Lokale Vorauswahl für sensible Felddaten oder Standorte nutzen.','Saisonale Kameraordner ohne verpflichtendes Cloud-Abo prüfen.'],cta:'Dauerhaft kostenlose Version · Keine Kreditkarte · Windows-Desktop-App'},
 sl:{hero:'TrailEye AI analizira fotografije in videe lovskih kamer na vašem računalniku Windows. Standardno zaznavanje in arhiviranje ne zahtevata nalaganja posnetkov v galerijo v oblaku.',proof:'Zasebne lokacije, časovne oznake in mape kamer lahko ostanejo pod vašim nadzorom na računalniku Windows.',intro:['Arhiv lovskih kamer lahko vsebuje ljudi, vozila, zasebno lastnino, natančne lokacije kamer in podatke o občutljivih vrstah. Lokalna obdelava zmanjša potrebo po pošiljanju tega arhiva drugi storitvi.'],cards:['TrailEye bere datoteke iz izbranih map in delovni arhiv zgradi lokalno.','Osnovna zaznava in orodja za pregled delujejo brez nalaganja velikih map kamer.','Lokacije kamer in opažanja divjadi ni treba vključiti v obvezni oblak ponudnika.','Free je trajno brezplačen. Explorer in Professional sta na voljo kot enkratni licenci.','Napovedi lahko potrdite, zavrnete ali preimenujete, namesto da bi rezultat AI obravnavali kot končno avtoriteto.','Potek ni omejen na eno povezano znamko lovske kamere ali naročniški ekosistem.'],prose:['Standardni sistem TrailEye na računalniku Windows analizira slike in videe za živali, ljudi in vozila. Zaznave živali je mogoče razvrstiti v knjižnico podprtih vrst. OCR časovnih oznak, pregled, filtri, prikazi aktivnosti, zemljevidi in izvozi so del namiznega programa.','Združljiva grafična strojna oprema lahko pospeši AI prek DirectML. Internetna povezava ni potrebna zgolj zato, da bi vsako izvorno datoteko pošiljali v spletno galerijo.','»Lokalno najprej« ne pomeni, da program nikoli ne komunicira z omrežnimi storitvami. Glede na funkcijo se internet lahko uporablja za zemljevide, preverjanje programske opreme ali licence ter izbirno iskanje v oblaku z besedilnim opisom.','Izbirno iskanje v oblaku je ločeno od standardnega lokalnega zaznavanja, zahteva lasten API ključ ponudnika in izbrane slike pošlje izbranemu ponudniku. Ne vključite ga, kadar mora projekt vse slike ohraniti brez povezave.','Lokalno shranjevanje pomaga pri nadzoru, vendar je uporabnik kamere še vedno odgovoren za zakonito postavitev, dostop, hrambo in razkrivanje podatkov. Posnetki ljudi, vozil ali sosednjih zemljišč so lahko osebni ali občutljivi podatki.','Oblačne platforme so koristne, kadar so ključni takojšen oddaljen prenos, sodelovanje ali mobilne kamere. Lokalni namizni program je primernejši, kadar posnetki prihajajo na SD-karticah ali diskih, je prenos omejen, lokacije občutljive ali želite arhiv neodvisen od naročnine kamere.','TrailEye ne želi nadomestiti vseh funkcij oblaka. Njegova naloga je ponuditi preprost Windows potek od običajnih map kamer do pregledanih in iskalnih rezultatov.'],lis:['Kamere postavite le tam, kjer imate zakonito podlago in dovoljenje.','Omejite dostop do map, poročil in izvoženih slik.','Iz javno deljenega gradiva odstranite natančne lokacije.','Po potrebi zameglite obraze in registrske tablice v javnih ali promocijskih primerih.','Pred pomembnimi odločitvami naj AI razvrstitve preveri človek.'],related:['Od surovih map do pregledanih dogodkov z živalmi, ljudmi in vozili.','Uporabite lokalni predizbor, kadar so terenski podatki ali lokacije občutljivi.','Preglejte sezonske mape brez obvezne naročnine na oblak.'],cta:'Trajno brezplačna različica · Brez kreditne kartice · Windows namizni program'},
 es:{hero:'TrailEye AI analiza fotos y vídeos de cámaras trampa en tu PC Windows. El flujo estándar de detección y archivo no exige subir el material a una galería en la nube.',proof:'Las ubicaciones privadas, marcas de tiempo y carpetas de cámaras pueden permanecer bajo control del usuario en el PC Windows.',intro:['Un archivo puede contener personas, vehículos, propiedad privada, ubicaciones exactas y observaciones de especies sensibles. El procesamiento local reduce la necesidad de transferirlo a otro servicio.'],cards:['TrailEye lee los archivos de las carpetas seleccionadas y crea el archivo de trabajo localmente.','Las herramientas principales de detección y revisión pueden usarse sin subir grandes carpetas.','Las ubicaciones y observaciones no tienen que formar parte de una nube obligatoria del proveedor.','Free es permanente. Explorer y Professional son licencias de pago único.','Confirma, rechaza o cambia etiquetas en lugar de tratar el resultado de IA como autoridad final.','El flujo no está limitado a una sola marca conectada ni a un ecosistema de suscripción.'],prose:['La canalización estándar analiza imágenes y vídeos para animales, personas y vehículos en el ordenador Windows. Las detecciones compatibles pueden refinarse con una biblioteca de especies compatibles. OCR, revisión, filtros, actividad, mapas y exportaciones forman parte del flujo de escritorio.','El hardware gráfico compatible puede acelerar la IA mediante DirectML. No hace falta una conexión solo para enviar cada archivo a una galería alojada.','“Local-first” no significa que la aplicación nunca use servicios de red. Según la función, puede acceder a mapas, validación de software o licencia y búsqueda opcional en la nube.','La búsqueda opcional en la nube es independiente del detector local, requiere la propia clave API del usuario y envía imágenes seleccionadas al proveedor elegido. Desactívala si el proyecto exige que todo permanezca offline.','Mantener los datos localmente mejora el control, pero el operador sigue siendo responsable de la colocación legal, acceso, retención y divulgación. Imágenes con personas, vehículos o propiedades vecinas pueden ser datos sensibles.','Las plataformas en la nube son útiles para entrega remota inmediata, colaboración o cámaras celulares. El software local encaja mejor con SD o discos, ancho de banda limitado, ubicaciones sensibles o archivos independientes de una suscripción.','TrailEye no pretende sustituir todas las funciones cloud, sino ofrecer un flujo Windows sencillo desde carpetas normales hasta resultados revisados y buscables.'],lis:['Coloca cámaras solo donde tengas base legal y autorización.','Limita el acceso a carpetas, informes e imágenes exportadas.','Elimina ubicaciones exactas del material compartido públicamente.','Difumina caras y matrículas cuando corresponda.','Haz que una persona revise clasificaciones importantes de IA.'],related:['Pasa de carpetas sin procesar a eventos revisados de animales, personas y vehículos.','Usa cribado local cuando los datos o ubicaciones sean sensibles.','Revisa carpetas de temporada sin suscripción obligatoria en la nube.'],cta:'Edición gratuita permanente · Sin tarjeta · Aplicación Windows'},
 ru:{hero:'TrailEye AI анализирует фото и видео фотоловушек на вашем ПК Windows. Стандартный процесс обнаружения и архива не требует загрузки материалов в облачную галерею.',proof:'Частные места, время и папки камер могут оставаться под контролем пользователя на ПК Windows.',intro:['Архив фотоловушек может содержать людей, транспорт, частную собственность, точные места камер и чувствительные виды. Локальная обработка уменьшает необходимость передавать архив стороннему сервису.'],cards:['TrailEye читает файлы из выбранных папок и создаёт рабочий архив локально.','Основные инструменты обнаружения и проверки работают без загрузки больших папок.','Места камер и наблюдения не обязаны попадать в облако поставщика.','Free остаётся бесплатной. Explorer и Professional — разовые лицензии.','Подтверждайте, отклоняйте или меняйте метки вместо того, чтобы считать результат ИИ окончательным.','Процесс не ограничен одной маркой камеры или подписной экосистемой.'],prose:['Стандартный процесс анализирует изображения и видео на животных, людей и транспорт на ПК Windows. Поддерживаемые животные уточняются по библиотеке из поддерживаемых видов. OCR, проверка, фильтры, активность, карты и экспорт входят в настольный процесс.','Совместимая графика может ускорить ИИ через DirectML. Сеть не нужна лишь для отправки каждого исходного файла в размещённую галерею.','Local-first не означает, что программа никогда не использует сеть. Карты, проверка ПО или лицензии и опциональный облачный поиск могут требовать подключения.','Облачный поиск отделён от локального детектора, требует собственного API-ключа и отправляет выбранные изображения указанному поставщику. Отключите его для строго офлайн-проектов.','Локальное хранение улучшает контроль, но оператор камеры отвечает за законное размещение, доступ, хранение и раскрытие данных. Изображения людей, транспорта или соседней собственности могут быть чувствительными.','Облачные платформы полезны для мгновенной удалённой доставки, совместной работы или сотовых камер. Локальное ПО лучше подходит для SD-карт, дисков, ограниченного интернета и чувствительных мест.','TrailEye не заменяет каждую облачную функцию. Его задача — простой Windows-процесс от обычных папок к проверенным, searchable результатам.'],lis:['Размещайте камеры только при законном основании и полномочиях.','Ограничивайте доступ к папкам, отчётам и экспортированным изображениям.','Удаляйте точные места из публичных материалов.','При необходимости размывайте лица и номера автомобилей.','Важные классификации ИИ проверяйте вручную.'],related:['От необработанных папок к проверенным событиям животных, людей и транспорта.','Используйте локальный отбор для чувствительных полевых данных или мест.','Проверяйте сезонные папки без обязательной облачной подписки.'],cta:'Постоянная бесплатная версия · Без карты · Приложение Windows'},
 zh:{hero:'TrailEye AI 在 Windows 电脑上分析野外相机照片和视频。标准检测和档案流程不要求把素材上传到云图库。',proof:'私人位置、时间戳和相机文件夹可以继续由用户在 Windows 电脑上掌控。',intro:['野外相机档案可能包含人员、车辆、私人财产、精确相机位置和敏感物种记录。本地处理可减少把整个档案传给其他服务的需要。'],cards:['TrailEye 从你选择的文件夹读取文件，并在本地建立工作档案。','核心检测和审核工具无需上传大型相机文件夹即可使用。','相机位置和野生动物记录无需进入强制供应商云端。','Free 永久免费。Explorer 和 Professional 为一次性许可。','确认、拒绝或重新标记预测，而不是把 AI 结果当成最终权威。','工作流程不受限于某一个联网相机品牌或订阅生态。'],prose:['TrailEye 标准流程在 Windows 电脑上分析动物、人员和车辆。支持的动物检测可细化到 支持的物种。时间戳 OCR、审核、筛选、活动视图、地图和导出都属于桌面工作流程。','兼容的 Windows 显卡可通过 DirectML 加速 AI。无需为了把每个源文件发送到托管图库而联网。','“本地优先”并不代表应用永远不会访问任何网络服务。地图、软件或许可验证以及可选的云搜索都可能使用网络。','可选云搜索与标准本地检测器分开，需要用户自己的 API 密钥，并把选定图像发送给所选提供商。如果项目要求所有图像保持离线，请不要启用。','本地保存提高了控制力，但相机操作者仍需对合法放置、访问、保留和披露负责。包含人员、车辆或邻近财产的图像可能属于敏感数据。','云平台适合即时远程传输、协作或蜂窝相机。本地桌面软件更适合 SD 卡或磁盘、有限带宽、敏感位置或希望档案不依赖相机订阅的用户。','TrailEye 不打算替代所有云功能。它的作用是提供从普通相机文件夹到已审核、可搜索结果的 Windows 工作流程。'],lis:['仅在有合法理由和权限的位置放置相机。','限制对文件夹、报告和导出图像的访问。','从公开分享的材料中删除精确位置。','适当时模糊公共或宣传示例中的人脸和车牌。','在做重要决定前由人工检查 AI 分类。'],related:['从原始文件夹整理为已审核的动物、人员和车辆事件。','对于敏感现场数据或位置使用本地初筛。','无需强制云订阅即可审核季节相机文件夹。'],cta:'永久免费版 · 无需信用卡 · Windows 桌面应用'}
},
research:{
 de:{hero:'TrailEye AI unterstützt Forschende und Naturschutzteams bei der Vorauswahl von Fotos und Videos, Prüfung von Vorhersagen, Wiederherstellung von Zeitstempeln, Untersuchung von Aktivitätsmustern und dem Export von Ergebnissen in einem Windows-Desktop-Workflow.',proof:'Aktivitätsansichten bleiben mit prüfbaren Erkennungen verbunden. KI-Ausgaben unterstützen die Vorauswahl und ersetzen keine Projektvalidierung.',intro:['TrailEye verbindet Schritte, die sonst oft auf Skripte, Tabellen, Medienbetrachter und Kartentools verteilt sind.'],cards:['Mit Fotos, Videos oder gemischten Medien in normalen Projektordnern starten.','Wahrscheinliche Tier-, Personen- und Fahrzeugereignisse vor der detaillierten menschlichen Prüfung hervorheben.','Tiererkennungen bei ausreichender Evidenz in eine Bibliothek unterstützter Arten verfeinern.','Vorhersagen bestätigen, ablehnen und neu beschriften, damit Unsicherheit nicht stillschweigend als Wahrheit gilt.','OCR, EXIF und Dateizeit sowie Kamerastandorte nutzen, um Feldkontext wiederherzustellen.','CSV, Excel, ausgewählte Bilder und PDF-Berichte für weitere Arbeit und Kommunikation erstellen.'],prose:['Kamerafallenbilder variieren nach Lebensraum, Region, Jahreszeit, Kameramodell, Beleuchtung und Tierentfernung. Ein Artenmodell kann sich zwischen Projekten unterschiedlich verhalten. TrailEye hält Vorhersagen deshalb prüf- und korrigierbar.','Vor dem operativen Einsatz sollten Recall und Artgenauigkeit an einem repräsentativen, zulässigen Datensatz aus dem eigenen Projekt geprüft werden. Für kritische Datensätze ist eine menschliche Validierung sinnvoll; Version, Modell, Einstellungen und Prüfprotokoll sollten dokumentiert werden.','Kamerafallen können Standorte gefährdeter Arten, Privatland, Personalbewegungen und unbeteiligte Personen zeigen. Der Standarddetektor läuft lokal auf Windows und verlangt keine gehostete Galerie.','Einige Funktionen können dennoch Netzwerkzugriff nutzen: Online-Karten, Lizenzvorgänge und optionale Cloud-Suche. Projekte mit strikten Offline-Regeln sollten diese Funktionen bewerten und deaktivieren.','Wildkameras blenden häufig Datum und Uhrzeit in Bildpixel ein. TrailEye kann OCR anwenden und EXIF oder Dateizeit als Rückfall nutzen. Zeitstempel und Sicherheit sollten geprüft werden, wenn Timing relevant ist.','Nach der Prüfung kann TrailEye Beobachtungen nach Art, Stunde und Tag zusammenfassen und Heatmaps sowie Sonnen- und Mondkontext zeigen. Kamerastandorte können manuell gesetzt oder aus GPS übernommen werden. Für formale Statistik sollten geeignete externe Werkzeuge genutzt werden.','Professional entfernt Workflow-Grenzen, macht KI-Vorhersagen aber nicht automatisch zu validierten biologischen Labels. Projektvalidierung bleibt notwendig.'],lis:['Free: vollständigen Erkennungsworkflow mit bis zu 20 Dateien pro Analyse testen.','Explorer: bis zu 1.000 Dateien aus einem Ordner pro Lauf auf einem Computer.','Professional: unbegrenzte Dateien, Ordnerbaum-Scan und drei Computeraktivierungen für Mehrkamera-Projekte.'],related:['Netzwerkgrenzen und lokale Verarbeitung sensibler Medien prüfen.','Den vollständigen Workflow vom Ordner zum Bericht verstehen.','Den individuellen Einsatz für Jäger und Landmanagement ansehen.'],cta:'Free-Version · Vollständige KI-Erkennung · Menschliche Prüfung bleibt wichtig'},
 sl:{hero:'TrailEye AI raziskovalcem in naravovarstvenim ekipam pomaga pri predizboru fotografij in videov, pregledu napovedi, pridobivanju časovnih oznak, raziskovanju vzorcev aktivnosti in izvozu rezultatov v Windows programu.',proof:'Prikazi aktivnosti ostanejo povezani s pregledljivimi zaznavami. Rezultat AI je pomoč pri predizboru, ne nadomestilo za projektno validacijo.',intro:['TrailEye združuje korake, ki so pogosto razdeljeni med skripte, preglednice, pregledovalnike medijev in kartografska orodja.'],cards:['Začnite s fotografijami, videi ali mešanimi mediji v običajnih projektnih mapah.','Pred podrobnim pregledom izpostavite verjetne dogodke z živalmi, ljudmi in vozili.','Ko ima model dovolj podatkov, razvrstite zaznave živali v knjižnico podprtih vrst.','Potrdite, zavrnite ali preimenujte napovedi, da negotovi rezultati ne postanejo samodejno »resnica«.','Za obnovitev terenskega konteksta uporabite OCR, EXIF, čas datoteke in zemljevide lokacij kamer.','Ustvarite CSV, Excel, izbrane slike in PDF poročila za nadaljnje delo in komunikacijo.'],prose:['Posnetki kamer se razlikujejo glede na habitat, geografijo, letni čas, model kamere, osvetlitev in oddaljenost živali. Model, ki je dober pri enem projektu, se lahko pri drugem obnaša drugače. TrailEye zato ohranja napovedi pregledljive in popravljive.','Pred uporabo ocenite zaznavanje in natančnost vrst na reprezentativnem dovoljenem vzorcu lastnih podatkov. Za ključne zapise ohranite človeško preverjanje ter dokumentirajte različico programske opreme, model, nastavitve in protokol pregleda.','Podatki kamer lahko razkrijejo lokacije ogroženih vrst, zasebna zemljišča, gibanje osebja in mimoidoče. Standardni zaznavalnik TrailEye deluje lokalno v Windows in ne zahteva gostovane galerije.','Nekatere funkcije lahko vseeno uporabljajo internet: zemljevidi, licenčne operacije in izbirno iskanje v oblaku. Projekti s strogo offline zahtevo naj te funkcije ocenijo in izklopijo.','Lovske kamere pogosto vtisnejo datum in čas neposredno v sliko. TrailEye lahko uporabi OCR, nato EXIF ali čas datoteke. Kadar je čas pomemben za analizo, je treba obnovljeno oznako preveriti.','Po pregledu lahko TrailEye povzame opažanja po vrsti, uri in dnevu ter pokaže toplotne karte, kontekst sonca in lune. Lokacije kamer lahko vnesete ročno ali iz GPS podatkov. Za formalno statistiko uporabite ustrezna zunanja orodja.','Professional odstrani omejitve poteka dela, vendar AI napovedi ne spremeni samodejno v validirane biološke oznake. Projektna validacija ostaja nujna.'],lis:['Free: za oceno celotnega prepoznavanja na do 20 datotek na analizo.','Explorer: do 1.000 datotek iz ene mape na zagon na enem računalniku.','Professional: neomejene datoteke, pregled drevesa map in tri aktivacije za projekte z več kamerami.'],related:['Preglejte omrežne meje in lokalno obdelavo občutljivih medijev.','Oglejte si celoten potek od mape do poročila.','Oglejte si uporabo za posameznike, lovce in upravljanje zemljišč.'],cta:'Brezplačna različica · Celotno AI prepoznavanje · Človeški pregled ostaja bistven'},
 es:{hero:'TrailEye AI ayuda a investigadores y equipos de conservación a cribar fotos y vídeos, revisar predicciones, recuperar tiempos, explorar actividad y exportar resultados desde Windows.',proof:'Las vistas de actividad siguen conectadas a detecciones revisables. La IA ayuda al cribado, no sustituye la validación del proyecto.',intro:['TrailEye combina pasos que a menudo están repartidos entre scripts, hojas de cálculo, visores y herramientas cartográficas.'],cards:['Empieza con fotos, vídeos o medios mixtos en carpetas normales del proyecto.','Destaca posibles eventos de animales, personas y vehículos antes de la revisión humana detallada.','Refina detecciones de animales con una biblioteca de especies compatibles cuando haya evidencia suficiente.','Confirma, rechaza o reetiqueta predicciones para que la incertidumbre no se trate como verdad.','Usa OCR, EXIF, hora de archivo y mapas de cámaras para recuperar el contexto de campo.','Genera CSV, Excel, imágenes seleccionadas e informes PDF para trabajo posterior.'],prose:['Las imágenes varían por hábitat, región, estación, modelo de cámara, iluminación y distancia. Un modelo puede comportarse distinto entre proyectos, por eso TrailEye mantiene las predicciones revisables y corregibles.','Antes del uso operativo, evalúa sensibilidad y precisión de especies con una muestra representativa y autorizada de tu despliegue. Mantén verificación humana para registros críticos y documenta versión, modelo, ajustes y protocolo.','Los datos pueden revelar especies amenazadas, terrenos privados, movimientos de personal y transeúntes. El detector estándar funciona localmente en Windows y no exige una galería alojada.','Algunas funciones pueden usar red: mapas online, licencias y búsqueda opcional en la nube. Los proyectos estrictamente offline deben valorar y desactivar estas funciones.','Las cámaras suelen imprimir fecha y hora en los píxeles. TrailEye puede aplicar OCR y usar EXIF o hora de archivo como respaldo. Revisa el tiempo recuperado cuando afecte al análisis.','Tras la revisión, TrailEye resume observaciones por especie, hora y día, con mapas de calor y contexto solar/lunar. Las ubicaciones pueden ponerse manualmente o derivarse de GPS. Usa herramientas adecuadas para análisis estadístico formal.','Professional elimina límites de flujo, pero no convierte automáticamente predicciones en etiquetas biológicas validadas. La validación del proyecto sigue siendo esencial.'],lis:['Free: evalúa el flujo completo con hasta 20 archivos por análisis.','Explorer: hasta 1.000 archivos de una carpeta por ejecución en un PC.','Professional: archivos ilimitados, árbol de carpetas y tres activaciones para proyectos multicámara.'],related:['Revisa límites de red y procesamiento local de medios sensibles.','Comprende el flujo completo de carpeta a informe.','Consulta el uso individual y de gestión de terrenos.'],cta:'Edición Free · Reconocimiento IA completo · La revisión humana sigue siendo esencial'},
 ru:{hero:'TrailEye AI помогает исследователям и природоохранным командам отбирать фото и видео, проверять прогнозы, восстанавливать время, изучать активность и экспортировать результаты в Windows.',proof:'Виды активности связаны с проверяемыми обнаружениями. ИИ помогает отбору, а не заменяет валидацию проекта.',intro:['TrailEye объединяет этапы, которые часто разделены между скриптами, таблицами, просмотрщиками и картографическими инструментами.'],cards:['Начните с фото, видео или смешанных данных в обычных папках проекта.','Выведите вероятные события с животными, людьми и транспортом до детальной проверки.','Уточняйте животных по библиотеке поддерживаемых видов, когда у модели достаточно данных.','Подтверждайте, отклоняйте и меняйте метки, чтобы неопределённость не считалась истиной.','Используйте OCR, EXIF, время файла и карту камер для восстановления полевого контекста.','Создавайте CSV, Excel, выбранные изображения и PDF для дальнейшей работы.'],prose:['Изображения фотоловушек различаются по среде, региону, сезону, камере, освещению и расстоянию. Одна модель может вести себя по-разному в разных проектах. TrailEye сохраняет прогнозы проверяемыми и исправляемыми.','До рабочего использования оцените полноту обнаружения и точность видов на репрезентативной разрешённой выборке. Сохраняйте человеческую проверку критичных записей и документируйте версию, модель, настройки и протокол.','Данные могут раскрывать места редких видов, частную территорию, движение персонала и прохожих. Стандартный детектор работает локально в Windows и не требует размещённой галереи.','Некоторые функции используют сеть: онлайн-карты, лицензии и опциональный облачный поиск. Строго офлайн-проекты должны оценить и отключить их.','Фотоловушки часто печатают дату и время прямо в изображении. TrailEye применяет OCR и использует EXIF или время файла как резерв. Проверяйте время, если оно влияет на анализ.','После проверки TrailEye может суммировать наблюдения по виду, часу и дню, показывать тепловые карты и солнечно-лунный контекст. Места камер задаются вручную или из GPS. Формальную статистику проводите в подходящей среде.','Professional снимает ограничения процесса, но не превращает прогнозы ИИ в валидированные биологические метки. Валидация проекта остаётся необходимой.'],lis:['Free: оценка полного процесса на 20 файлах за анализ.','Explorer: до 1 000 файлов из одной папки за запуск на одном компьютере.','Professional: неограниченные файлы, дерево папок и три активации для многокамерных проектов.'],related:['Проверьте сетевые границы и локальную обработку чувствительных данных.','Изучите полный процесс от папки до отчёта.','Посмотрите индивидуальный сценарий для охотников и управления землёй.'],cta:'Free-версия · Полное ИИ-распознавание · Человеческая проверка остаётся обязательной'},
 zh:{hero:'TrailEye AI 帮助研究人员和保护团队对照片和视频进行初筛、检查预测、恢复时间戳、探索活动规律，并在 Windows 工作流程中导出结果。',proof:'活动视图始终与可审核检测结果关联。AI 用于辅助初筛，而不是替代项目验证。',intro:['TrailEye 把常被分散到脚本、电子表格、媒体查看器和地图工具中的步骤整合到一个工作流程。'],cards:['从普通项目文件夹中的照片、视频或混合媒体开始。','在人工详细审核前优先显示可能的动物、人员和车辆事件。','当模型证据充分时，把动物检测细化到 受支持物种库。','确认、拒绝和重新标记预测，避免把不确定结果静默当成事实。','使用 OCR、EXIF、文件时间和相机位置地图恢复现场上下文。','生成 CSV、Excel、选定图像和 PDF 报告用于后续工作与沟通。'],prose:['相机陷阱图像会随栖息地、地区、季节、相机型号、光照和动物距离而变化。一个项目表现良好的模型在另一个项目可能不同，因此 TrailEye 保持预测可审核、可修正。','投入使用前，应在自己部署中的代表性、授权样本上评估检测召回和物种精度。项目关键记录应保留人工验证，并记录软件版本、模型、设置和审核协议。','相机陷阱数据可能暴露濒危物种位置、私人土地、人员活动和路人。TrailEye 标准检测器在 Windows 本地运行，不要求把档案放入托管图库。','某些功能仍可能使用网络：在线地图、许可操作和可选云搜索。严格离线项目应评估并关闭这些功能。','相机经常把日期和时间直接烧录到图像像素中。TrailEye 可用 OCR，并以 EXIF 或文件时间为备用。当时间影响分析时，应审核恢复的时间戳。','审核后，TrailEye 可按物种、小时和日期汇总观察，并显示热力图、太阳时段和月亮信息。相机位置可手动放置或来自 GPS。正式统计分析应使用适当的后续工具。','Professional 取消工作流程限制，但不会自动把 AI 预测变成已验证的生物学标签。项目级验证仍然必要。'],lis:['Free：每次分析最多 20 个文件，用于评估完整识别流程。','Explorer：每次从一个文件夹处理最多 1,000 个文件，可在一台电脑上使用。','Professional：文件不限量、支持文件夹树，并可激活三台电脑用于多相机项目。'],related:['检查敏感媒体的网络边界和本地处理。','了解完整的文件夹到报告工作流程。','查看个人、猎人和土地管理使用场景。'],cta:'免费版 · 完整 AI 识别 · 人工审核仍然必要'}
},
hunters:{
 de:{hero:'TrailEye AI verwandelt Ordner mit Wildkamera-Fotos und -Videos in ein prüfbares Archiv mit Wildtiererkennungen, Artenvorhersagen, Zeitstempeln, Aktivitätsansichten und Kamerastandortkarten auf deinem Windows-PC.',proof:'Originalbild, vorhergesagte Art, Zeitstempel und Ereigniskontext bleiben während der Prüfung zusammen.',intro:['TrailEye übernimmt den repetitiven ersten Durchlauf, während du entscheidest, welche Sichtungen für Grundstück, Habitatpflege oder Jagdplanung relevant sind.'],cards:['Wahrscheinliche Tierereignisse vor der Detailprüfung von Personen-, Fahrzeug- und irrelevanten Ereignissen trennen.','Die Bibliothek unterstützter Arten als Ausgangspunkt nutzen und Ergebnisse anschließend bestätigen oder korrigieren.','Eingeblendete Zeitstempel per OCR lesen und Metadaten oder Dateizeit als Rückfall nutzen.','Beobachtungen nach Stunde, Tag, Sonnenphase und verfügbarem Mondkontext prüfen.','Erkennungen mit manuell gesetzten Standorten oder verfügbarem Foto-GPS verknüpfen.','Daten-, Bild- und Berichtsexporte für Landbesitzer, Vereinsmitglieder oder Verwaltungsakten erstellen.'],prose:['Saisonale Archive enthalten oft Fotos, Serien und kurze Clips. TrailEye analysiert Fotos und Videos aus normalen Ordnern in einem Desktop-Workflow.','Eine Wildkamera zeichnet nur auf, was ihre Erfassungszone passiert. Position, Empfindlichkeit, Vegetation, Wetter und Bewegungsrichtung beeinflussen das Archiv. TrailEye zeigt Muster in den gesammelten Daten, kann aber weder Abwesenheit beweisen noch zukünftige Bewegung sicher vorhersagen.','Stündliche und tägliche Aktivität, Sonnenphasen und Standortfilter sollten zusammen mit Feldwissen, Spuren, Habitatbedingungen und geltenden Jagdregeln genutzt werden.','Kameraordner können Grundstücke, Menschen, Fahrzeuge und genaue Wildtierstandorte zeigen. Die Standardanalyse läuft lokal unter Windows, sodass die Dateien nicht in eine verpflichtende Cloud-Galerie müssen. Das passt auch zu nicht-zellularen Kameras und schwacher Verbindung.','Kartenkacheln, Lizenzierung und optionale Cloud-Suche können Netzwerkzugriff verwenden. Die optionale Textsuche benötigt einen eigenen API-Schlüssel und ist von der lokalen Erkennung getrennt.','TrailEye startet mit Dateien von Speicherkarte, Festplatte oder bestehendem Archiv und ist nicht an einen Hersteller gebunden. Kompatibilität und Zeitstempelqualität können variieren, daher sollte Free mit eigenem Material getestet werden.','Explorer und Professional sind Einmallizenzen, keine laufenden Abonnements.','Technik sollte verantwortliche Entscheidungen unterstützen, nicht Urteilsvermögen oder Regeln ersetzen. Lokale Jagd- und Kameravorschriften sind einzuhalten; Personen- oder Fahrzeugerkennungen dürfen nicht für Belästigung, Stalking oder rechtswidrige Überwachung genutzt werden.'],lis:['Free: bis zu 20 Fotos oder Videos pro Analyse – ausreichend für Kompatibilitäts- und Erkennungstests.','Explorer: bis zu 1.000 Dateien pro Analyse aus einem Ordner für eine aktive Kamera.','Professional: unbegrenzte Dateien und Unterordner für mehrere Kameras, Standorte oder ganze Saisonarchive.'],related:['Den gesamten Weg vom gemischten Kameraordner zum geprüften Archiv ansehen.','Erfahren, wie lokale Verarbeitung das Material unter deiner Kontrolle hält.','Validierung, Korrektur und Export für Felddatensätze prüfen.'],cta:'Dauerhaft kostenlose Version · Vollständige KI-Erkennung · Keine Kreditkarte'},
 sl:{hero:'TrailEye AI spremeni mape fotografij in videov lovskih kamer v pregledljiv arhiv z zaznavami divjadi, napovedmi podprtih vrst, časovnimi oznakami, prikazi aktivnosti in zemljevidi lokacij kamer na vašem Windows računalniku.',proof:'Med pregledovanjem ostanejo izvirna slika, napovedana vrsta, časovna oznaka in kontekst dogodka skupaj.',intro:['TrailEye opravi ponavljajoči prvi pregled, vi pa odločite, katera opažanja so pomembna za vaše zemljišče, habitat ali načrtovanje lova.'],cards:['Pred podrobnim pregledom ločite verjetne živalske dogodke od ljudi, vozil in nepomembnih posnetkov.','Knjižnico podprtih vrst uporabite kot izhodišče, nato rezultat potrdite ali popravite.','Z OCR preberite časovne oznake na sliki ter po potrebi uporabite metapodatke ali čas datoteke.','Opažanja preglejte po urah, dnevih, delu dneva in razpoložljivem kontekstu lune.','Zaznave povežite z ročno postavljenimi lokacijami ali GPS podatki fotografij, kjer so na voljo.','Ustvarite podatkovne, slikovne in poročevalske izvoze za lastnike zemljišč, člane društev ali evidence upravljanja.'],prose:['Sezonski arhivi pogosto vsebujejo fotografije, rafale in kratke videe. TrailEye analizira fotografije in videe iz običajnih map v enem namiznem poteku dela.','Lovska kamera zabeleži le tisto, kar gre skozi njeno območje zaznavanja. Postavitev, občutljivost, vegetacija, vreme in smer gibanja živali vplivajo na arhiv. TrailEye lahko pokaže vzorce v zbranih posnetkih, ne more pa dokazati odsotnosti živali ali zanesljivo napovedati prihodnjega gibanja.','Urno in dnevno aktivnost, kontekst dela dneva in filtre lokacij uporabljajte skupaj s terenskim znanjem, sledmi, habitatom in veljavnimi lovskimi predpisi.','Mape kamer lahko razkrijejo razporeditev zemljišč, ljudi, vozila in natančne lokacije divjadi. Standardna analiza TrailEye deluje lokalno v Windows, zato datotek ni treba nalagati v obvezno galerijo v oblaku. To ustreza tudi kameram brez mobilne povezave.','Zemljevidi, licenciranje in izbirno iskanje v oblaku lahko uporabljajo internet. Izbirno besedilno iskanje zahteva lasten API ključ in je ločeno od lokalnega zaznavanja.','TrailEye začne z datotekami, kopiranimi s kartice, diska ali obstoječega arhiva in ni vezan na enega proizvajalca. Združljivost in kakovost časovnih oznak se lahko razlikujeta, zato pred nakupom preizkusite Free na svojih posnetkih.','Explorer in Professional sta enkratni licenci in ne naročnini.','Tehnologija naj podpira odgovorno odločanje, ne pa nadomešča presoje ali pravil. Upoštevajte lokalno zakonodajo in lovske predpise glede kamer, podatkov v realnem času in postavitve. Zaznav ljudi ali vozil ne uporabljajte za nadlegovanje, zalezovanje ali nezakonit nadzor.'],lis:['Free: do 20 fotografij ali videov na analizo – dovolj za preverjanje združljivosti in prepoznavanja na vaših posnetkih.','Explorer: do 1.000 datotek na analizo iz ene mape, namenjeno eni aktivni kameri.','Professional: neomejene datoteke in pregled podmap za več kamer, lokacij ali celotne sezonske strukture map.'],related:['Oglejte si celoten proces od mešane mape kamere do pregledanega arhiva.','Spoznajte, kako lokalna obdelava ohrani posnetke pod vašim nadzorom.','Preglejte vidike validacije, popravkov in izvoza za terenske podatke.'],cta:'Trajno brezplačna različica · Celotno AI prepoznavanje · Brez kreditne kartice'},
 es:{hero:'TrailEye AI convierte carpetas de fotos y vídeos en un archivo revisable con detecciones de fauna, predicciones de especies, tiempos, actividad y mapas de ubicaciones, todo en Windows.',proof:'La imagen original, especie predicha, fecha y contexto permanecen juntos durante la revisión.',intro:['TrailEye realiza la primera pasada repetitiva, mientras tú decides qué observaciones importan para tu propiedad, hábitat o planificación.'],cards:['Separa posibles animales de eventos con personas, vehículos o irrelevantes antes de la revisión detallada.','Usa la biblioteca de especies compatibles como punto de partida y confirma o corrige el resultado.','Lee marcas de tiempo con OCR y usa metadatos o tiempo del archivo como respaldo.','Revisa observaciones por hora, día, periodo solar y contexto lunar disponible.','Relaciona detecciones con sitios colocados manualmente o GPS de fotos.','Crea exportaciones de datos, imágenes e informes para propietarios, clubes o registros.'],prose:['Los archivos de temporada suelen mezclar fotos, ráfagas y clips cortos. TrailEye analiza fotos y vídeos de carpetas normales en un único flujo de escritorio.','Una cámara solo registra lo que pasa por su zona de detección. Colocación, sensibilidad, vegetación, clima y dirección influyen en el archivo. TrailEye puede mostrar patrones, pero no demostrar ausencia ni predecir movimiento futuro con certeza.','Usa actividad horaria y diaria, periodos solares y filtros de ubicación junto con conocimiento de campo, rastros, hábitat y normativa aplicable.','Las carpetas pueden mostrar propiedad, personas, vehículos y ubicaciones exactas. El análisis estándar se ejecuta localmente en Windows, sin galería cloud obligatoria, y funciona bien con cámaras no celulares.','Mapas, licencias y búsqueda opcional en la nube pueden usar red. La búsqueda por texto requiere tu propia API y es independiente de la detección local.','TrailEye empieza con archivos copiados de tarjeta, disco o archivo existente y no está ligado a un fabricante. La compatibilidad y los tiempos pueden variar, por lo que conviene probar Free con tus propios medios.','Explorer y Professional son licencias de pago único, no suscripciones.','La tecnología debe apoyar decisiones responsables, no sustituir el juicio ni las reglas. Cumple leyes y normas de caza; no uses detecciones de personas o vehículos para acoso, seguimiento o vigilancia ilegal.'],lis:['Free: hasta 20 fotos o vídeos por análisis, suficiente para probar compatibilidad y reconocimiento.','Explorer: hasta 1.000 archivos por análisis desde una carpeta, pensado para una cámara activa.','Professional: archivos ilimitados y subcarpetas para múltiples cámaras, sitios o temporadas completas.'],related:['Consulta todo el proceso desde carpeta mixta hasta archivo revisado.','Entiende cómo el procesamiento local mantiene el material bajo tu control.','Revisa validación, corrección y exportación para datos de campo.'],cta:'Edición gratuita permanente · Reconocimiento IA completo · Sin tarjeta'},
 ru:{hero:'TrailEye AI превращает папки фото и видео фотоловушек в проверяемый архив с обнаружениями, прогнозами видов, временем, активностью и картами мест камер на вашем ПК Windows.',proof:'Исходное изображение, предполагаемый вид, время и контекст события остаются вместе при проверке.',intro:['TrailEye выполняет повторяющийся первый проход, а вы решаете, какие наблюдения важны для участка, среды или планирования охоты.'],cards:['Отделяйте вероятных животных от людей, транспорта и неважных событий до детальной проверки.','Используйте библиотеку поддерживаемых видов как отправную точку, затем подтверждайте или исправляйте результат.','Читайте встроенное время через OCR и используйте метаданные или время файла как резерв.','Изучайте наблюдения по часу, дню, солнечному периоду и доступному лунному контексту.','Связывайте обнаружения с вручную заданными местами или GPS фотографий.','Создавайте экспорт данных, изображений и отчётов для владельцев, клубов или учёта.'],prose:['Сезонные архивы часто содержат фото, серии и короткие видео. TrailEye анализирует фото и видео из обычных папок в одном процессе.','Камера записывает только то, что проходит в зоне обнаружения. Положение, чувствительность, растительность, погода и направление движения влияют на архив. TrailEye показывает закономерности в собранных данных, но не доказывает отсутствие животного и не гарантирует будущие перемещения.','Используйте почасовую и дневную активность, солнечный контекст и фильтры мест вместе с полевыми знаниями, следами, средой и действующими правилами.','Папки могут раскрывать план участка, людей, транспорт и точные места животных. Стандартный анализ работает локально в Windows, поэтому файлы не нужно помещать в обязательную облачную галерею.','Карты, лицензии и опциональный облачный поиск могут использовать сеть. Текстовый поиск требует собственного API-ключа и отделён от локального обнаружения.','TrailEye работает с файлами с карты, диска или существующего архива и не привязан к одному производителю. Совместимость и качество времени различаются, поэтому Free стоит проверить на собственных данных.','Explorer и Professional — разовые лицензии, а не подписки.','Технологии должны поддерживать ответственное решение, а не заменять правила и суждение. Соблюдайте законы и охотничьи нормы; не используйте обнаружения людей или транспорта для преследования или незаконного наблюдения.'],lis:['Free: до 20 фото или видео за анализ — достаточно для проверки совместимости и распознавания.','Explorer: до 1 000 файлов за анализ из одной папки для активной камеры.','Professional: неограниченные файлы и подпапки для нескольких камер, мест или сезонных деревьев.'],related:['Посмотрите полный путь от смешанной папки к проверенному архиву.','Узнайте, как локальная обработка сохраняет материалы под вашим контролем.','Изучите вопросы валидации, исправлений и экспорта полевых данных.'],cta:'Постоянная бесплатная версия · Полное ИИ-распознавание · Без банковской карты'},
 zh:{hero:'TrailEye AI 把野外相机照片和视频文件夹转成可审核档案，包含野生动物检测、物种预测、时间戳、活动视图和相机位置地图，并在 Windows 电脑上运行。',proof:'审核时，原始图像、预测物种、时间戳和事件上下文始终保持关联。',intro:['TrailEye 完成重复的第一轮筛选，而你决定哪些观察对土地、栖息地工作或狩猎计划真正重要。'],cards:['在详细审核前把可能的动物事件与人员、车辆和无关事件分开。','使用 受支持物种预测库作为起点，然后确认或修正结果。','使用 OCR 读取画面时间戳，并以元数据或文件时间作为备用。','按小时、日期、太阳时段和可用月亮信息查看观察。','把检测结果与手动设置的位置或照片 GPS 关联。','为土地所有者、俱乐部成员或管理记录导出数据、图像和报告。'],prose:['季节档案常混有照片、连拍和短视频。TrailEye 从普通文件夹分析照片和视频，在一个桌面工作流程中完成审核。','野外相机只记录经过检测区域的内容。相机位置、灵敏度、植被、天气和动物方向都会影响档案。TrailEye 可揭示已收集影像中的规律，但不能证明动物不存在，也不能保证未来移动。','应把小时和日期活动、太阳时段和相机位置筛选与现场知识、足迹、栖息地条件和适用狩猎法规结合使用。','相机文件夹可能暴露土地布局、人员、车辆和精确野生动物位置。TrailEye 标准分析在 Windows 本地运行，因此无需强制云图库，也适合非蜂窝相机和网络较差地点。','地图、许可和可选云搜索可能使用网络。可选文字搜索需要你自己的 API 密钥，并与本地检测分开。','TrailEye 从相机卡、磁盘或现有档案复制的文件开始，不绑定某一个相机制造商。文件兼容性和时间戳质量可能不同，购买前应使用 Free 测试自己的素材。','Explorer 和 Professional 都是一次性许可，不是持续订阅。','技术应支持负责任的决策，而不是替代判断和规则。遵守当地法律和狩猎法规，不要把人员或车辆检测用于骚扰、跟踪或非法监控。'],lis:['Free：每次分析最多 20 张照片或视频，足以验证兼容性和识别效果。','Explorer：每次从一个文件夹分析最多 1,000 个文件，适合单台活跃相机。','Professional：文件不限量并支持子文件夹，适合多台相机、多个地点或完整季节档案。'],related:['查看从混合相机文件夹到已审核档案的完整流程。','了解本地处理如何让影像始终由你掌控。','查看现场数据的验证、修正和导出注意事项。'],cta:'永久免费版 · 完整 AI 识别 · 无需信用卡'}
},
best:{
 de:{hero:'Die beste Wildkamera-Software ist nicht einfach das Werkzeug mit den meisten KI-Labels. Sie sollte Prüfzeit verkürzen, Originalmaterial bewahren, unsichere Vorhersagen korrigierbar machen, Aktivitätsmuster zeigen und zum tatsächlichen Kamera-Workflow passen.',proof:'TrailEye kombiniert Ereigniserkennung, Artenvorhersage, Zeitstempel, Prüfwerkzeuge und Timeline-Kontext in einem Windows-Workflow.',intro:['Diese Funktionen machen den größten Unterschied, sobald ein Kameraarchiv über einige Dutzend Dateien hinauswächst.'],cards:['Ein erster Detektor sollte leere oder irrelevante Dateien ausblenden und prüfenswerte Ereignisse hervorheben.','Artenvorhersage ist nützlich, wenn sie prüfbar bleibt. Gute Software erlaubt Bestätigen, Ablehnen und Neubeschriften unsicherer Ergebnisse.','Bei Privatland, Jagdgebieten und Forschung kann lokale Analyse vermeiden, dass ein ganzes Archiv nur für Standarderkennung hochgeladen werden muss.','Kameraeinblendungen, EXIF und Dateizeit sind wichtig. Gute Software sollte Zeitkontext wiederherstellen.','Sortierung ist nur der erste Schritt. Wertvoller ist die Frage, wann eine ausgewählte Art, Person oder ein Fahrzeug tatsächlich aktiv ist.','Mehrkamera-Projekte sind leichter zu interpretieren, wenn Erkennungen einzelnen Kamerastandorten zugeordnet werden können.','Optionale Cloud-KI mit natürlicher Sprache hilft bei visuellen Details außerhalb einer festen Artenliste.'],prose:['Ein einfacher Sortierer kann Tierbilder von leeren Frames trennen. Mit wachsendem Archiv werden Organisation, Validierung und Interpretation wichtiger: Welche Art erschien wann, an welcher Kamera und wie vertrauenswürdig ist das Ergebnis?','Ein vollständiger Workflow sollte Originalbild oder -video mit jeder Erkennung verknüpfen und menschliche Korrekturen erlauben. KI soll repetitive Arbeit reduzieren, nicht Belege verbergen.','Cloud-Analyse kann leistungsfähig sein, aber das Hochladen aller Dateien kann langsam, teuer oder für private Standorte unerwünscht sein. Ein lokaler Workflow hält Standarderkennung auf dem Windows-PC und nutzt Internetdienste nur gezielt.','TrailEye folgt diesem Modell: Tier-, Personen- und Fahrzeugerkennung läuft lokal, optionale Cloud-KI ermöglicht flexible Suchanfragen über feste Klassen hinaus.','Nachtlicht, teilweise sichtbare Tiere, Bewegungsunschärfe, Vegetation und ungewöhnliche Winkel fordern jedes Modell. Ein Konfidenzwert hilft, aber Bestätigen, Ablehnen oder Korrigieren ist wichtiger.','TrailEye bietet Vorschläge für unterstützte Wildtierarten und hält jede Vorhersage in einem menschlich prüfbaren Workflow.','Mit zuverlässigen Zeitstempeln beantwortet das Archiv Fragen, die bloße Sortierung nicht kann. TrailEye zeigt stündliche und tägliche Aktivität und filtert nach Art, allen Tieren, Personen oder Fahrzeugen.','So lässt sich zum Beispiel Hirschaktivität von menschlichem Verkehr unterscheiden, statt alle Ereignisse in einem Diagramm zu mischen.','TrailEye passt besonders gut, wenn ein Windows-Workflow mit lokaler Erkennung, Artenvorhersage, Zeitstempeln, prüfbaren Klassifikationen, Heatmaps, Standortkarten und Exporten gewünscht ist. Fotos und kurze Videos werden gemeinsam verarbeitet.','Free testet bis zu 20 Dateien pro Analyse. Explorer unterstützt bis zu 1.000 Dateien aus einem Ordner, Professional entfernt das Dateilimit, unterstützt Ordnerbäume und drei Aktivierungen.','Teste eigenes schwieriges Material: Nacht-IR, entfernte oder teilweise sichtbare Tiere, Vegetation, Bewegungsunschärfe und gemischte Foto-/Videoordner. Prüfe, wie leicht Fehlalarme entfernt werden können und wie nützlich Exporte bleiben.','Vergleiche auch den Workflow selbst. Ein gutes Modell kann Zeit verschwenden, wenn Prüfen, Korrigieren oder Wiederfinden vergangener Ereignisse umständlich ist.'],related:['Vom Rohordner auf der SD-Karte zu geprüften Wildtierereignissen.','Was lokal läuft und wann Internet genutzt werden kann.','Prüfbare KI, Zeitstempel, Karten, Heatmaps und Exporte für Feldprojekte.','Wildtiermuster nach Zeit und Kamerastandort finden, ohne jede Datei manuell zu öffnen.'],cta:'Dauerhaft kostenlose Version · Lokale KI-Erkennung · Keine Kreditkarte'},
 sl:{hero:'Najboljši program za lovske kamere ni preprosto tisti z največ AI oznakami. Skrajšati mora čas pregleda, ohraniti izvirne posnetke, omogočiti popravljanje negotovih napovedi, pokazati vzorce aktivnosti in ustrezati načinu, kako dejansko uporabljate mape kamer.',proof:'TrailEye združuje zaznavanje dogodkov, napoved vrste, časovne oznake, orodja za pregled in kontekst časovnice v enem Windows poteku dela.',intro:['To so zmogljivosti, ki naredijo največjo razliko, ko arhiv kamer preseže nekaj deset datotek.'],cards:['Prvi zaznavalnik naj izloči prazne ali nepomembne datoteke in izpostavi dogodke, vredne pregleda.','Napoved vrste je koristna, če jo je mogoče pregledati. Program naj omogoča potrditev, zavrnitev ali popravek negotovih rezultatov.','Na zasebnih zemljiščih, loviščih in raziskovalnih lokacijah lokalna analiza prepreči nepotrebno nalaganje celotnega arhiva samo zaradi osnovnega zaznavanja.','Oznake na sliki, EXIF in čas datoteke so pomembni. Dober program mora obnoviti časovni kontekst.','Razvrščanje je šele prvi korak. Pomembnejše vprašanje je, kdaj je izbrana vrsta, oseba ali vozilo dejansko aktivno.','Projekte z več kamerami je veliko lažje razlagati, če so zaznave povezane s posameznimi lokacijami kamer.','Izbirni AI v oblaku z naravnim jezikom je uporaben, ko iščete vizualno podrobnost, ki ni del vnaprej določenega seznama vrst.'],prose:['Osnovni razvrščevalnik lahko loči slike živali od praznih posnetkov. Ko arhiv zraste, pa postanejo večji problem organizacija, validacija in interpretacija: katera vrsta se je pojavila, kdaj, na kateri kameri in ali je rezultat AI zanesljiv.','Celovit potek mora vsak rezultat ohraniti povezan z izvirno sliko ali videom ter omogočiti človeški popravek. AI naj zmanjša ponavljajoče delo, ne skriva dokazov.','Analiza v oblaku je lahko zmogljiva, vendar je nalaganje vsake datoteke lahko počasno, drago ali nezaželeno pri zasebnih lokacijah. Lokalni potek ohrani standardno zaznavanje na Windows računalniku in internet uporablja le tam, kjer prinese jasno korist.','TrailEye sledi temu modelu: standardno zaznavanje živali, ljudi in vozil deluje lokalno, izbirni AI v oblaku pa omogoča prilagodljiva iskanja zunaj vgrajenih razredov.','Nočna osvetlitev, delno vidne živali, zameglitev, vegetacija in nenavadni koti lahko zmedejo vsak model. Ocena zaupanja pomaga, vendar je možnost potrditve, zavrnitve ali popravka pomembnejša.','TrailEye trenutno vključuje knjižnico podprtih vrst divjadi in napovedi ohranja v poteku s človeškim pregledom.','Ko imajo zaznave zanesljive časovne oznake, arhiv odgovori na vprašanja, ki jih navadno razvrščanje ne more. TrailEye prikazuje urno in dnevno aktivnost ter analizo filtrira na izbrano vrsto, vse živali, ljudi ali vozila.','Tako lahko na primer ločite aktivnost jelenjadi od človeškega prometa, namesto da bi bili vsi dogodki združeni v enem grafu.','TrailEye je posebej primeren, če želite Windows program, ki združuje lokalno zaznavanje, napoved vrst, časovne oznake, pregledljive razvrstitve, toplotne karte, zemljevide lokacij in izvoze. Fotografije in kratki videi delujejo v istem poteku.','Free omogoča test do 20 datotek na analizo. Explorer podpira do 1.000 datotek iz ene mape, Professional pa odstrani omejitev datotek, podpira drevesa map in tri aktivacije.','Pred nakupom preizkusite svoje zahtevne posnetke: nočne IR slike, oddaljene in delno vidne živali, vegetacijo, zameglitev ter mešane mape fotografij in videov. Preverite, kako enostavno je zavrniti napačne rezultate in kako uporabni so izvozi.','Primerjajte tudi sam potek dela. Natančen model lahko še vedno izgublja čas, če so pregled, popravljanje in iskanje preteklih dogodkov nerodni.'],related:['Kako iz surove mape na SD-kartici pridete do pregledanih dogodkov z divjadjo.','Kaj deluje lokalno in kdaj se lahko uporablja internetna povezava.','Pregledljiv AI, časovne oznake, zemljevidi, toplotne karte in izvozi za terenske projekte.','Poiščite vzorce divjadi po času in lokaciji kamere brez ročnega odpiranja vsake datoteke.'],cta:'Trajno brezplačna različica · Lokalno AI prepoznavanje · Brez kreditne kartice'},
 es:{hero:'El mejor software no es simplemente el que tiene más etiquetas de IA. Debe reducir tiempo de revisión, conservar la evidencia original, permitir corregir predicciones dudosas, revelar patrones y adaptarse a cómo usas tus carpetas.',proof:'TrailEye combina detección de eventos, predicción de especies, tiempos, controles de revisión y contexto temporal en un flujo Windows.',intro:['Estas son las capacidades que más importan cuando un archivo crece más allá de unas pocas decenas de archivos.'],cards:['El primer detector debe apartar archivos vacíos o irrelevantes y destacar eventos que merecen revisión.','La predicción de especies es útil si sigue siendo revisable. Busca software que permita confirmar, rechazar o reetiquetar.','En terrenos privados, zonas de caza o investigación, el análisis local evita subir todo el archivo para una detección estándar.','Superposiciones, EXIF y tiempos de archivo importan. Un buen programa debe recuperar el contexto temporal.','Clasificar es solo el primer paso. La pregunta valiosa es cuándo está activa una especie, persona o vehículo concreto.','Los proyectos multicámara son más fáciles de interpretar cuando las detecciones se conectan a ubicaciones individuales.','La IA opcional en la nube con lenguaje natural ayuda a buscar detalles fuera de listas predefinidas.'],prose:['Un clasificador básico separa animales de imágenes vacías, pero al crecer el archivo los problemas pasan a ser organización, validación e interpretación: qué especie apareció, cuándo, en qué cámara y si el resultado es fiable.','Un flujo completo debe mantener la imagen o vídeo original unido a cada detección y permitir correcciones humanas. La IA debe reducir trabajo repetitivo, no ocultar evidencia.','El análisis cloud puede ser potente, pero subir cada archivo puede ser lento, caro o indeseable en ubicaciones privadas. Un flujo local mantiene la detección estándar en Windows y usa internet solo cuando aporta valor.','TrailEye sigue ese modelo: detección de animales, personas y vehículos local, con IA cloud opcional para búsquedas flexibles más allá de clases fijas.','La iluminación nocturna, animales parciales, desenfoque, vegetación y ángulos inusuales desafían cualquier modelo. Una puntuación ayuda, pero poder confirmar, rechazar o corregir importa más.','TrailEye incluye actualmente especies compatibles y mantiene las predicciones dentro de un flujo de revisión humana.','Con tiempos fiables, el archivo responde preguntas que la simple clasificación no puede. TrailEye muestra actividad horaria y diaria y filtra por especie, animales, personas o vehículos.','Así puedes separar, por ejemplo, actividad de ciervos de tráfico humano en vez de mezclar todos los eventos.','TrailEye encaja especialmente bien si buscas un flujo Windows con detección local, especies, tiempos, revisión, mapas de calor, ubicaciones y exportaciones. Admite fotos y vídeos cortos juntos.','Free prueba hasta 20 archivos por análisis. Explorer admite hasta 1.000 de una carpeta y Professional elimina el límite, admite árboles de carpetas y tres activaciones.','Prueba tus propias imágenes difíciles: IR nocturno, animales lejanos o parciales, vegetación, desenfoque y carpetas mixtas. Comprueba que sea fácil rechazar falsos positivos y que las exportaciones sean útiles.','Compara también el flujo de trabajo. Un modelo preciso puede perder tiempo si revisar, corregir y encontrar eventos pasados es incómodo.'],related:['Cómo pasar de una carpeta SD sin procesar a eventos revisados.','Qué funciona localmente y cuándo puede usarse internet.','IA revisable, tiempos, mapas, mapas de calor y exportaciones para campo.','Encuentra patrones por tiempo y ubicación sin abrir manualmente cada archivo.'],cta:'Edición gratuita permanente · IA local · Sin tarjeta'},
 ru:{hero:'Лучшее ПО для фотоловушек — не просто инструмент с максимальным числом ИИ-меток. Оно должно сокращать время проверки, сохранять оригиналы, позволять исправлять сомнительные прогнозы, показывать активность и соответствовать вашему процессу.',proof:'TrailEye объединяет обнаружение событий, прогноз видов, время, инструменты проверки и временной контекст в одном Windows-процессе.',intro:['Эти возможности сильнее всего влияют на работу, когда архив вырастает за несколько десятков файлов.'],cards:['Первичный детектор должен убрать пустые или неважные файлы и показать события, которые стоит проверить.','Прогноз вида полезен, если его можно проверить. Ищите возможность подтвердить, отклонить или изменить сомнительные результаты.','Для частных участков, охоты и исследований локальный анализ позволяет не загружать весь архив ради стандартного обнаружения.','Наложенное время, EXIF и время файла важны. Хорошее ПО должно восстанавливать временной контекст.','Сортировка — только первый шаг. Важнее понять, когда активны конкретный вид, человек или транспорт.','Многокамерные проекты проще понимать, если обнаружения связаны с конкретными местами камер.','Опциональный облачный ИИ на естественном языке полезен для деталей вне фиксированного списка видов.'],prose:['Базовый сортировщик отделяет животных от пустых кадров, но при росте архива главными становятся организация, валидация и интерпретация: какой вид появился, когда, на какой камере и насколько надёжен результат.','Полный процесс должен сохранять исходное фото или видео рядом с обнаружением и позволять человеку исправлять сомнительные классификации. ИИ должен сокращать рутину, а не скрывать доказательства.','Облачный анализ может быть мощным, но загрузка каждого файла бывает медленной, дорогой или нежелательной для частных мест. Локальный процесс держит стандартное обнаружение на Windows и использует интернет только при конкретной пользе.','TrailEye следует этому подходу: животные, люди и транспорт обнаруживаются локально, а облачный ИИ опционально используется для гибкого поиска за пределами встроенных классов.','Ночной свет, частично видимые животные, смаз, растительность и необычные углы затрудняют работу любой модели. Оценка уверенности полезна, но возможность подтвердить, отклонить или исправить важнее.','TrailEye сейчас включает библиотеку поддерживаемых видов и оставляет прогнозы в процессе человеческой проверки.','С надёжным временем архив отвечает на вопросы, которые простая сортировка не решает. TrailEye показывает почасовую и дневную активность и фильтрует по виду, всем животным, людям или транспорту.','Это позволяет, например, отделить активность оленей от человеческого движения вместо смешивания всех событий.','TrailEye особенно подходит, если нужен Windows-процесс с локальным обнаружением, видами, временем, проверяемыми классификациями, тепловыми картами, местами камер и экспортом. Фото и короткие видео работают вместе.','Free позволяет проверить до 20 файлов за анализ. Explorer — до 1 000 из одной папки, Professional снимает лимит, поддерживает дерево папок и три активации.','Тестируйте собственные сложные кадры: ночной ИК, дальних или частично видимых животных, растительность, смаз и смешанные папки. Проверьте, легко ли отклонять ложные срабатывания и полезен ли экспорт.','Сравнивайте и сам процесс. Даже точная модель может тратить время, если проверка, исправление и поиск прошлых событий неудобны.'],related:['От сырой папки SD-карты к проверенным событиям животных.','Что работает локально и когда может использоваться интернет.','Проверяемый ИИ, время, карты, тепловые карты и экспорт для полевых проектов.','Находите закономерности по времени и месту без ручного открытия каждого файла.'],cta:'Постоянная бесплатная версия · Локальное ИИ-распознавание · Без банковской карты'},
 zh:{hero:'最好的野外相机软件并不只是 AI 标签最多的工具。它应缩短审核时间、保留原始证据、允许修正不确定预测、揭示活动规律，并适合你真实使用相机文件夹的方式。',proof:'TrailEye 在一个 Windows 工作流程中结合事件检测、物种预测、时间戳、审核控件和时间轴上下文。',intro:['当相机档案超过几十个文件后，这些能力会带来最大差异。'],cards:['第一轮检测应把空白或无关文件移出视线，并突出值得审核的事件。','物种预测只有在可审核时才有价值。好的软件应允许确认、拒绝或重标不确定结果。','对于私人土地、狩猎区和研究地点，本地分析可避免仅为了标准检测就上传整个档案。','相机叠加时间、EXIF 和文件时间都很重要。好的软件应恢复时间上下文。','分类只是第一步。更有价值的问题是某个物种、人员或车辆究竟何时活跃。','当检测结果能关联到具体相机位置时，多相机项目更容易解释。','可选的自然语言云 AI 适合搜索预定义物种列表之外的视觉细节。'],prose:['基础分类器可以把动物图像与空白画面分开，但随着档案增长，真正困难的是组织、验证和解释：哪种动物何时出现、由哪台相机记录、AI 结果是否可信。','完整工作流程应把原始照片或视频与每个检测结果保持关联，并允许人工修正不确定分类。AI 应减少重复工作，而不是隐藏证据。','云分析可能很强，但上传每个文件可能很慢、成本高，或不适合私人相机位置。本地优先流程把标准检测留在 Windows 电脑上，只在有明确价值时使用互联网服务。','TrailEye 遵循这个模式：动物、人员和车辆的标准检测在本地运行，可选云 AI 用于超出内置类别的灵活自然语言搜索。','夜间照明、局部动物、运动模糊、植被和异常角度都会挑战任何模型。置信分数有帮助，但能确认、拒绝或重标结果更重要。','TrailEye 提供受支持物种的预测，并把这些预测保留在人工审核流程中。','一旦检测有可靠时间戳，档案就能回答普通分类无法回答的问题。TrailEye 可显示小时和日期活动，并按指定物种、所有动物、人员或车辆筛选。','例如，可以把鹿的活动与人员交通分开，而不是把所有事件混进一张通用图表。','如果你想要一个结合本地检测、物种预测、时间戳、可审核分类、热力图、相机位置地图和导出的 Windows 工作流程，TrailEye 很适合。照片和短视频可统一处理。','Free 每次可测试最多 20 个文件。Explorer 支持一个文件夹最多 1,000 个文件，Professional 取消文件限制、支持文件夹树并允许三台电脑激活。','购买前使用你自己的困难图像测试：夜间红外、远距离或局部动物、植被、运动模糊以及照片/视频混合文件夹。检查误报是否容易拒绝，以及导出结果是否实用。','还要比较工作流程本身。即使模型准确，如果审核、修正和查找过去事件很麻烦，仍会浪费时间。'],related:['了解如何从原始 SD 卡文件夹得到已审核的野生动物事件。','了解哪些功能在本地运行，以及何时可能使用互联网。','用于现场项目的可审核 AI、时间戳、地图、热力图和导出。','无需手动打开每个文件即可按时间和相机位置寻找野生动物规律。'],cta:'永久免费版 · 本地 AI 识别 · 无需信用卡'}
}
};
const d=D[page]?.[lang];if(!d)return;
function setOne(sel,text){const el=document.querySelector(sel);if(el&&text)el.textContent=text}
function setMany(sel,arr){if(!arr)return;document.querySelectorAll(sel).forEach((el,i)=>{if(arr[i])el.textContent=arr[i]})}
setOne('.hero-lede',d.hero);setOne('.landing-proof p',d.proof);
setMany('.landing-heading > p:not(.kicker)',d.intro);
setMany('.landing-card p',d.cards);setMany('.prose > p',d.prose);setMany('.prose li',d.lis);setMany('.related-pages span',d.related);setOne('.landing-cta p',d.cta);
const ops={de:{SELECT:'AUSWÄHLEN',ANALYZE:'ANALYSIEREN',REVIEW:'PRÜFEN',ORGANIZE:'ORGANISIEREN',UNDERSTAND:'VERSTEHEN',EXPORT:'EXPORTIEREN',CONTROL:'KONTROLLE',CONNECTIVITY:'VERBINDUNG',LOCATION:'STANDORT',COST:'KOSTEN',CAMERA:'KAMERA',INGEST:'IMPORT',DETECT:'ERKENNEN',REFINE:'VERFEINERN',CORRECT:'KORRIGIEREN',CONTEXT:'KONTEXT',SORT:'SORTIEREN',IDENTIFY:'BESTIMMEN',TIME:'ZEIT',PATTERN:'MUSTER',PLACE:'ORT',SHARE:'TEILEN',TRIAGE:'VORAUSWAHL',SPECIES:'ARTEN',PRIVACY:'DATENSCHUTZ',INSIGHT:'ANALYSE',FLEXIBILITY:'FLEXIBILITÄT'},sl:{SELECT:'IZBERI',ANALYZE:'ANALIZIRAJ',REVIEW:'PREGLEJ',ORGANIZE:'UREDI',UNDERSTAND:'RAZUMI',EXPORT:'IZVOZI',CONTROL:'NADZOR',CONNECTIVITY:'POVEZAVA',LOCATION:'LOKACIJA',COST:'STROŠEK',CAMERA:'KAMERA',INGEST:'UVOZ',DETECT:'ZAZNAJ',REFINE:'DOLOČI',CORRECT:'POPRAVI',CONTEXT:'KONTEKST',SORT:'RAZVRSTI',IDENTIFY:'PREPOZNAJ',TIME:'ČAS',PATTERN:'VZOREC',PLACE:'KRAJ',SHARE:'DELI',TRIAGE:'PREDIZBOR',SPECIES:'VRSTA',PRIVACY:'ZASEBNOST',INSIGHT:'VPOGLED',FLEXIBILITY:'PRILAGODLJIVOST'},es:{SELECT:'SELECCIONAR',ANALYZE:'ANALIZAR',REVIEW:'REVISAR',ORGANIZE:'ORGANIZAR',UNDERSTAND:'ENTENDER',EXPORT:'EXPORTAR',CONTROL:'CONTROL',CONNECTIVITY:'CONEXIÓN',LOCATION:'UBICACIÓN',COST:'COSTE',CAMERA:'CÁMARA',INGEST:'IMPORTAR',DETECT:'DETECTAR',REFINE:'REFINAR',CORRECT:'CORREGIR',CONTEXT:'CONTEXTO',SORT:'CLASIFICAR',IDENTIFY:'IDENTIFICAR',TIME:'TIEMPO',PATTERN:'PATRÓN',PLACE:'LUGAR',SHARE:'COMPARTIR',TRIAGE:'CRIBADO',SPECIES:'ESPECIES',PRIVACY:'PRIVACIDAD',INSIGHT:'ANÁLISIS',FLEXIBILITY:'FLEXIBILIDAD'},ru:{SELECT:'ВЫБОР',ANALYZE:'АНАЛИЗ',REVIEW:'ПРОВЕРКА',ORGANIZE:'ОРГАНИЗАЦИЯ',UNDERSTAND:'АНАЛИТИКА',EXPORT:'ЭКСПОРТ',CONTROL:'КОНТРОЛЬ',CONNECTIVITY:'СВЯЗЬ',LOCATION:'МЕСТО',COST:'СТОИМОСТЬ',CAMERA:'КАМЕРА',INGEST:'ИМПОРТ',DETECT:'ОБНАРУЖЕНИЕ',REFINE:'УТОЧНЕНИЕ',CORRECT:'ИСПРАВЛЕНИЕ',CONTEXT:'КОНТЕКСТ',SORT:'СОРТИРОВКА',IDENTIFY:'ОПРЕДЕЛЕНИЕ',TIME:'ВРЕМЯ',PATTERN:'МОДЕЛЬ',PLACE:'МЕСТО',SHARE:'ЭКСПОРТ',TRIAGE:'ОТБОР',SPECIES:'ВИДЫ',PRIVACY:'ПРИВАТНОСТЬ',INSIGHT:'АНАЛИЗ',FLEXIBILITY:'ГИБКОСТЬ'},zh:{SELECT:'选择',ANALYZE:'分析',REVIEW:'审核',ORGANIZE:'整理',UNDERSTAND:'理解',EXPORT:'导出',CONTROL:'控制',CONNECTIVITY:'连接',LOCATION:'位置',COST:'成本',CAMERA:'相机',INGEST:'导入',DETECT:'检测',REFINE:'细化',CORRECT:'修正',CONTEXT:'上下文',SORT:'分类',IDENTIFY:'识别',TIME:'时间',PATTERN:'规律',PLACE:'地点',SHARE:'分享',TRIAGE:'初筛',SPECIES:'物种',PRIVACY:'隐私',INSIGHT:'洞察',FLEXIBILITY:'灵活性'}};
document.querySelectorAll('.landing-card > span').forEach(el=>{const m=el.textContent.match(/^(\d+)\s*\/\s*(.+)$/);if(m&&ops[lang]?.[m[2].trim()])el.textContent=m[1]+' / '+ops[lang][m[2].trim()]});
})();